import React, { useState, useEffect } from 'react';
// All CSS is now inlined for self-contained execution

// Main App Component
const App = () => {
  // State to control sidebar visibility (for hamburger menu)
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  // State for the description modal (Gemini API feature)
  const [showDescriptionModal, setShowDescriptionModal] = useState(false);
  const [modalContent, setModalContent] = useState('');
  const [isLoadingDescription, setIsLoadingDescription] = useState(false);
  // State for the cart modal
  const [showCartModal, setShowCartModal] = useState(false);
  // State for the profile page
  const [showProfilePage, setShowProfilePage] = useState(false);
  // State for search term
  const [searchTerm, setSearchTerm] = useState('');
  // State for generic message box (replaces alert())
  const [showMessageBox, setShowMessageBox] = useState(false);
  const [messageBoxContent, setMessageBoxContent] = useState('');


  // Mock data for food categories and items
  const initialFoodCategories = [
    {
      id: 'pizzas',
      name: 'Breakfast',
