        content={modalContent}
        isOpen={showDescriptionModal}
        onClose={() => setShowDescriptionModal(false)}
        isLoading={isLoadingDescription}
      />
      <CartModal
        cartItems={cartItems}
        foodCategories={initialFoodCategories} // Pass initial categories to look up item details
        isOpen={showCartModal}
        onClose={() => setShowCartModal(false)}
        updateQuantity={updateQuantity}
        openMessageBox={(message) => { setMessageBoxContent(message); setShowMessageBox(true); }}
      />
      <ProfilePage
        isOpen={showProfilePage}
        onClose={() => setShowProfilePage(false)}
      />
      <MessageBox
        content={messageBoxContent}
        isOpen={showMessageBox}
        onClose={() => setShowMessageBox(false)}
      />
    </div>
  );
};

export default App;
